@page "/apply"
@rendermode InteractiveServer
@using sv_57a2d7851a88432fb4548e53e46ccb8f.Models
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<h2 class="mb-4">Job Application</h2>

<!-- Step Indicator Bar -->
<div class="step-indicator mb-4">
    @for (int i = 0; i < _stepNames.Length; i++)
    {
        var stepIndex = i;
        var isCompleted = stepIndex < _currentStep;
        var isCurrent = stepIndex == _currentStep;
        var isFuture = stepIndex > _currentStep;

        <div class="step-item @(isCurrent ? "current" : "") @(isCompleted ? "completed" : "") @(isFuture ? "future" : "")"
             @onclick="() => GoToStep(stepIndex)"
             role="button"
             tabindex="0">
            <div class="step-circle">
                @if (isCompleted)
                {
                    <span>✓</span>
                }
                else
                {
                    <span>@(stepIndex + 1)</span>
                }
            </div>
            <div class="step-label">@_stepNames[stepIndex]</div>
        </div>

        @if (stepIndex < _stepNames.Length - 1)
        {
            <div class="step-connector @(stepIndex < _currentStep ? "completed" : "")"></div>
        }
    }
</div>

@if (!string.IsNullOrEmpty(_errorMessage))
{
    <div class="alert alert-danger">@_errorMessage</div>
}

<!-- Step 1: Personal Info -->
@if (_currentStep == 0)
{
    <div class="card">
        <div class="card-header"><h4>Personal Information</h4></div>
        <div class="card-body">
            <div class="mb-3">
                <label class="form-label">Full Name <span class="text-danger">*</span></label>
                <input type="text" class="form-control" @bind="_fullName" />
            </div>
            <div class="mb-3">
                <label class="form-label">Email <span class="text-danger">*</span></label>
                <input type="email" class="form-control" @bind="_email" />
                @if (!string.IsNullOrEmpty(_emailError))
                {
                    <div class="text-danger mt-1">@_emailError</div>
                }
            </div>
            <div class="mb-3">
                <label class="form-label">Phone <span class="text-danger">*</span></label>
                <input type="tel" class="form-control" @bind="_phone" />
            </div>
            <div class="mb-3">
                <label class="form-label">Address <span class="text-danger">*</span></label>
                <textarea class="form-control" rows="2" @bind="_address"></textarea>
            </div>
            <div class="d-flex justify-content-end">
                <button class="btn btn-primary" @onclick="NextFromPersonalInfo" disabled="@_isValidating">
                    @if (_isValidating)
                    {
                        <span class="spinner-border spinner-border-sm me-1"></span>
                        <span>Validating…</span>
                    }
                    else
                    {
                        <span>Next →</span>
                    }
                </button>
            </div>
        </div>
    </div>
}

<!-- Step 2: Work History -->
@if (_currentStep == 1)
{
    <div class="card">
        <div class="card-header"><h4>Work History</h4></div>
        <div class="card-body">
            @for (int i = 0; i < _workEntries.Count; i++)
            {
                var idx = i;
                <div class="border rounded p-3 mb-3 position-relative">
                    <h5>Position @(idx + 1)</h5>
                    @if (_workEntries.Count > 1)
                    {
                        <button class="btn btn-sm btn-outline-danger position-absolute top-0 end-0 m-2"
                                @onclick="() => RemoveWorkEntry(idx)">Remove</button>
                    }
                    <div class="row">
                        <div class="col-md-6 mb-3">
                            <label class="form-label">Company Name <span class="text-danger">*</span></label>
                            <input type="text" class="form-control" @bind="_workEntries[idx].Company" />
                        </div>
                        <div class="col-md-6 mb-3">
                            <label class="form-label">Job Title <span class="text-danger">*</span></label>
                            <input type="text" class="form-control" @bind="_workEntries[idx].Title" />
                        </div>
                    </div>
                    <div class="row">
                        <div class="col-md-4 mb-3">
                            <label class="form-label">Start Date <span class="text-danger">*</span></label>
                            <input type="date" class="form-control" @bind="_workEntries[idx].StartDate" />
                        </div>
                        <div class="col-md-4 mb-3">
                            <label class="form-label">End Date</label>
                            <input type="date" class="form-control" @bind="_workEntries[idx].EndDate"
                                   disabled="@_workEntries[idx].IsCurrent" />
                        </div>
                        <div class="col-md-4 mb-3 d-flex align-items-end">
                            <div class="form-check">
                                <input type="checkbox" class="form-check-input" id="current-@idx"
                                       @bind="_workEntries[idx].IsCurrent" />
                                <label class="form-check-label" for="current-@idx">Currently working here</label>
                            </div>
                        </div>
                    </div>
                    <div class="mb-3">
                        <label class="form-label">Description</label>
                        <textarea class="form-control" rows="3" @bind="_workEntries[idx].Description"></textarea>
                    </div>
                </div>
            }
            <button class="btn btn-outline-secondary mb-3" @onclick="AddWorkEntry">+ Add Another Position</button>
            <div class="d-flex justify-content-between">
                <button class="btn btn-secondary" @onclick="PreviousStep">← Back</button>
                <button class="btn btn-primary" @onclick="NextFromWorkHistory">Next →</button>
            </div>
        </div>
    </div>
}

<!-- Step 3: References -->
@if (_currentStep == 2)
{
    <div class="card">
        <div class="card-header"><h4>References</h4></div>
        <div class="card-body">
            @for (int i = 0; i < _references.Count; i++)
            {
                var idx = i;
                <div class="border rounded p-3 mb-3 position-relative">
                    <h5>Reference @(idx + 1)</h5>
                    @if (_references.Count > 1)
                    {
                        <button class="btn btn-sm btn-outline-danger position-absolute top-0 end-0 m-2"
                                @onclick="() => RemoveReference(idx)">Remove</button>
                    }
                    <div class="row">
                        <div class="col-md-6 mb-3">
                            <label class="form-label">Name <span class="text-danger">*</span></label>
                            <input type="text" class="form-control" @bind="_references[idx].Name" />
                        </div>
                        <div class="col-md-6 mb-3">
                            <label class="form-label">Relationship <span class="text-danger">*</span></label>
                            <input type="text" class="form-control" @bind="_references[idx].Relationship" />
                        </div>
                    </div>
                    <div class="row">
                        <div class="col-md-6 mb-3">
                            <label class="form-label">Email <span class="text-danger">*</span></label>
                            <input type="email" class="form-control" @bind="_references[idx].Email" />
                        </div>
                        <div class="col-md-6 mb-3">
                            <label class="form-label">Phone <span class="text-danger">*</span></label>
                            <input type="tel" class="form-control" @bind="_references[idx].Phone" />
                        </div>
                    </div>
                </div>
            }
            @if (_references.Count < 3)
            {
                <button class="btn btn-outline-secondary mb-3" @onclick="AddReference">+ Add Reference</button>
            }
            <div class="d-flex justify-content-between">
                <button class="btn btn-secondary" @onclick="PreviousStep">← Back</button>
                <button class="btn btn-primary" @onclick="NextFromReferences">Next →</button>
            </div>
        </div>
    </div>
}

<!-- Step 4: Cover Letter -->
@if (_currentStep == 3)
{
    <div class="card">
        <div class="card-header"><h4>Cover Letter</h4></div>
        <div class="card-body">
            <div class="mb-3">
                <textarea class="form-control" rows="12" maxlength="2000"
                          @bind="_coverLetter" @bind:event="oninput"></textarea>
                <div class="text-muted mt-1">@(_coverLetter?.Length ?? 0) / 2000 characters</div>
            </div>
            <div class="d-flex justify-content-between">
                <button class="btn btn-secondary" @onclick="PreviousStep">← Back</button>
                <button class="btn btn-primary" @onclick="NextStep">Next →</button>
            </div>
        </div>
    </div>
}

<!-- Step 5: Review & Submit -->
@if (_currentStep == 4)
{
    @if (_isSubmitted)
    {
        <div class="card">
            <div class="card-body text-center py-5">
                <div class="text-success mb-3" style="font-size: 3rem;">✓</div>
                <h3 class="text-success">Application Submitted!</h3>
                <p class="lead">Your application ID is <strong>#@_applicationId</strong></p>
                <p class="text-muted">Thank you for applying. We will review your application and get back to you soon.</p>
            </div>
        </div>
    }
    else
    {
        <div class="card mb-3">
            <div class="card-header d-flex justify-content-between align-items-center">
                <h5 class="mb-0">Personal Information</h5>
                <button class="btn btn-sm btn-link" @onclick='() => GoToStep(0)'>Edit</button>
            </div>
            <div class="card-body">
                <dl class="row mb-0">
                    <dt class="col-sm-3">Full Name</dt>
                    <dd class="col-sm-9">@_fullName</dd>
                    <dt class="col-sm-3">Email</dt>
                    <dd class="col-sm-9">@_email</dd>
                    <dt class="col-sm-3">Phone</dt>
                    <dd class="col-sm-9">@_phone</dd>
                    <dt class="col-sm-3">Address</dt>
                    <dd class="col-sm-9">@_address</dd>
                </dl>
            </div>
        </div>

        <div class="card mb-3">
            <div class="card-header d-flex justify-content-between align-items-center">
                <h5 class="mb-0">Work History</h5>
                <button class="btn btn-sm btn-link" @onclick='() => GoToStep(1)'>Edit</button>
            </div>
            <div class="card-body">
                @foreach (var entry in _workEntries)
                {
                    <div class="mb-3 pb-3 border-bottom">
                        <strong>@entry.Title</strong> at <strong>@entry.Company</strong><br />
                        <span class="text-muted">
                            @entry.StartDate.ToString("MMM yyyy") –
                            @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy") ?? "N/A")
                        </span>
                        @if (!string.IsNullOrWhiteSpace(entry.Description))
                        {
                            <p class="mt-1 mb-0">@entry.Description</p>
                        }
                    </div>
                }
            </div>
        </div>

        <div class="card mb-3">
            <div class="card-header d-flex justify-content-between align-items-center">
                <h5 class="mb-0">References</h5>
                <button class="btn btn-sm btn-link" @onclick='() => GoToStep(2)'>Edit</button>
            </div>
            <div class="card-body">
                @foreach (var r in _references)
                {
                    <div class="mb-2">
                        <strong>@r.Name</strong> (@r.Relationship)<br />
                        <span class="text-muted">@r.Email · @r.Phone</span>
                    </div>
                }
            </div>
        </div>

        <div class="card mb-3">
            <div class="card-header d-flex justify-content-between align-items-center">
                <h5 class="mb-0">Cover Letter</h5>
                <button class="btn btn-sm btn-link" @onclick='() => GoToStep(3)'>Edit</button>
            </div>
            <div class="card-body">
                <p style="white-space: pre-wrap;">@_coverLetter</p>
            </div>
        </div>

        <div class="d-flex justify-content-between">
            <button class="btn btn-secondary" @onclick="PreviousStep">← Back</button>
            <button class="btn btn-success btn-lg" @onclick="SubmitApplication" disabled="@_isSubmitting">
                @if (_isSubmitting)
                {
                    <span class="spinner-border spinner-border-sm me-1"></span>
                    <span>Submitting…</span>
                }
                else
                {
                    <span>Submit Application</span>
                }
            </button>
        </div>
    }
}

@code {
    private static readonly string[] _stepNames =
    {
        "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"
    };

    private int _currentStep;
    private string? _errorMessage;
    private string? _emailError;
    private bool _isValidating;
    private bool _isSubmitting;
    private bool _isSubmitted;
    private int _applicationId;

    // Step 1
    private string _fullName = "";
    private string _email = "";
    private string _phone = "";
    private string _address = "";

    // Step 2
    private List<WorkEntryModel> _workEntries = new() { new WorkEntryModel() };

    // Step 3
    private List<ReferenceModel> _references = new() { new ReferenceModel() };

    // Step 4
    private string _coverLetter = "";

    private void GoToStep(int step)
    {
        if (step < _currentStep)
        {
            _errorMessage = null;
            _currentStep = step;
        }
    }

    private void NextStep()
    {
        _errorMessage = null;
        _currentStep++;
    }

    private void PreviousStep()
    {
        _errorMessage = null;
        _currentStep--;
    }

    private async Task NextFromPersonalInfo()
    {
        _errorMessage = null;
        _emailError = null;

        if (string.IsNullOrWhiteSpace(_fullName) || string.IsNullOrWhiteSpace(_email) ||
            string.IsNullOrWhiteSpace(_phone) || string.IsNullOrWhiteSpace(_address))
        {
            _errorMessage = "Please fill in all required fields.";
            return;
        }

        _isValidating = true;
        try
        {
            var isValid = await ApplicationService.ValidateEmailAsync(_email);
            if (!isValid)
            {
                _emailError = "Please enter a valid email address.";
                return;
            }
            NextStep();
        }
        finally
        {
            _isValidating = false;
        }
    }

    private void NextFromWorkHistory()
    {
        _errorMessage = null;
        foreach (var entry in _workEntries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title) ||
                entry.StartDate == default)
            {
                _errorMessage = "Please fill in Company, Title, and Start Date for all positions.";
                return;
            }
        }
        NextStep();
    }

    private void NextFromReferences()
    {
        _errorMessage = null;
        foreach (var r in _references)
        {
            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship) ||
                string.IsNullOrWhiteSpace(r.Email) || string.IsNullOrWhiteSpace(r.Phone))
            {
                _errorMessage = "Please fill in all fields for each reference.";
                return;
            }
        }
        NextStep();
    }

    private void AddWorkEntry() => _workEntries.Add(new WorkEntryModel());
    private void RemoveWorkEntry(int index) => _workEntries.RemoveAt(index);

    private void AddReference()
    {
        if (_references.Count < 3)
            _references.Add(new ReferenceModel());
    }

    private void RemoveReference(int index) => _references.RemoveAt(index);

    private async Task SubmitApplication()
    {
        _isSubmitting = true;
        _errorMessage = null;
        try
        {
            var personal = new PersonalInfo(_fullName, _email, _phone, _address);
            var workHistory = new WorkHistory(_workEntries.Select(e =>
                new WorkEntry(e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description ?? ""))
                .ToList());
            var refs = _references.Select(r =>
                new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();

            var application = new JobApplication(personal, workHistory, refs, _coverLetter ?? "");
            _applicationId = await ApplicationService.SubmitApplicationAsync(application);
            _isSubmitted = true;
        }
        catch (Exception ex)
        {
            _errorMessage = $"Submission failed: {ex.Message}";
        }
        finally
        {
            _isSubmitting = false;
        }
    }

    private class WorkEntryModel
    {
        public string Company { get; set; } = "";
        public string Title { get; set; } = "";
        public DateTime StartDate { get; set; }
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string? Description { get; set; }
    }

    private class ReferenceModel
    {
        public string Name { get; set; } = "";
        public string Relationship { get; set; } = "";
        public string Email { get; set; } = "";
        public string Phone { get; set; } = "";
    }
}

.step-indicator {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 0;
}

.step-item {
    display: flex;
    flex-direction: column;
    align-items: center;
    cursor: default;
    min-width: 90px;
}

.step-item.completed {
    cursor: pointer;
}

.step-circle {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: bold;
    font-size: 0.9rem;
    border: 2px solid #dee2e6;
    background: #fff;
    color: #6c757d;
    transition: all 0.2s;
}

.step-item.current .step-circle {
    border-color: #0d6efd;
    background: #0d6efd;
    color: #fff;
}

.step-item.completed .step-circle {
    border-color: #198754;
    background: #198754;
    color: #fff;
}

.step-item.future .step-circle {
    opacity: 0.5;
}

.step-label {
    margin-top: 6px;
    font-size: 0.75rem;
    text-align: center;
    color: #6c757d;
    white-space: nowrap;
}

.step-item.current .step-label {
    color: #0d6efd;
    font-weight: 600;
}

.step-item.completed .step-label {
    color: #198754;
}

.step-item.future .step-label {
    opacity: 0.5;
}

.step-connector {
    flex: 1;
    height: 2px;
    background: #dee2e6;
    margin: 0 4px;
    margin-bottom: 22px;
    min-width: 30px;
    max-width: 80px;
    transition: background 0.2s;
}

.step-connector.completed {
    background: #198754;
}

